import csv

def parse_quarterly_results(csv_path: str) -> list[dict]:
    results = []
    with open(csv_path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f, delimiter=';')
        for row in reader:
            revenue = float(row['przychody_mln'].replace(',', '.'))
            ebit = float(row['ebit_mln'].replace(',', '.'))
            if revenue == 0:
                continue
            results.append({
                'quarter': row['kwartal'],
                'revenue_mln': revenue,
                'ebit_mln': ebit,
                'ebit_margin_pct': round(ebit / revenue * 100, 1)
            })
    return results

# Usage example:
data = parse_quarterly_results('wyniki.csv')
print(data[0])  # {'quarter': 'Q1 2025', 'revenue_mln': 267.4, 'ebit_mln': 38.2, 'ebit_margin_pct': 14.3}

import hashlib
import json
from pathlib import Path

def compute_content_hash(content: bytes) -> str:
    return hashlib.sha256(content).hexdigest()

def find_new_documents(current_docs: dict, cache_path: str) -> list[str]:
    cache_file = Path(cache_path)
    try:
        cached = json.loads(cache_file.read_text(encoding='utf-8'))
    except FileNotFoundError:
        cached = {}

    new_or_changed = []
    updated_cache = {}

    for url, content in current_docs.items():
        h = compute_content_hash(content)
        updated_cache[url] = h
        if cached.get(url) != h:
            new_or_changed.append(url)

    cache_file.write_text(json.dumps(updated_cache, indent=2), encoding='utf-8')
    return new_or_changed

