import pytest

def test_new_document_detected(tmp_path):
    cache = tmp_path / 'cache.json'
    docs = {'https://example.com/report.pdf': b'content_v1'}
    result = find_new_documents(docs, str(cache))
    assert 'https://example.com/report.pdf' in result

def test_unchanged_document_not_returned(tmp_path):
    cache = tmp_path / 'cache.json'
    docs = {'https://example.com/report.pdf': b'content_v1'}
    find_new_documents(docs, str(cache))  # first run — builds cache
    result = find_new_documents(docs, str(cache))  # second run — same content
    assert 'https://example.com/report.pdf' not in result

import pandas as pd

def dcf_valuation(base_nopat, g1, n, g2, wacc, net_debt, shares):
    pv_cfs = 0.0
    for t in range(1, n + 1):
        cf = base_nopat * (1 + g1) ** t
        pv_cfs += cf / (1 + wacc) ** t

    cf_n = base_nopat * (1 + g1) ** n
    tv = cf_n * (1 + g2) / (wacc - g2)       # terminal value at end of year N
    pv_tv = tv / (1 + wacc) ** n              # discount to present

    ev = pv_cfs + pv_tv
    equity = ev - net_debt
    price = equity / shares

    return {'ev_mln': round(ev, 1), 'equity_value_mln': round(equity, 1), 'price_per_share': round(price, 2)}

def dcf_sensitivity(base_params, wacc_range, g2_range):
    rows = {}
    for w in wacc_range:
        row = {}
        for g in g2_range:
            params = {**base_params, 'wacc': w, 'g2': g}
            row[f'g2={g:.1%}'] = dcf_valuation(**params)['price_per_share']
        rows[f'WACC={w:.1%}'] = row
    return pd.DataFrame(rows).T

