import re

def parse_markdown_table(table_text: str, float_columns: list) -> list:
    lines = [l.strip() for l in table_text.strip().splitlines()]
    lines = [l for l in lines if l.startswith('|')]

    def is_separator(line):
        return bool(re.match(r'^[|\s:\-]+$', line))

    def split_row(line):
        parts = line.strip('|').split('|')
        return [p.strip() for p in parts]

    header = None
    result = []
    for line in lines:
        if is_separator(line):
            continue
        cells = split_row(line)
        if header is None:
            header = cells
            continue
        row = {}
        for key, val in zip(header, cells):
            if val == '':
                row[key] = None
            elif key in float_columns:
                row[key] = float(val.replace(',', '.'))
            else:
                row[key] = val
        result.append(row)
    return result

import time
import threading
import functools

class RateLimiter:
    def __init__(self, calls_per_second: float, max_burst: int = 1):
        self.rate = calls_per_second
        self.max_burst = max_burst
        self.tokens = float(max_burst)
        self.last_time = time.monotonic()
        self.lock = threading.Lock()

    def acquire(self) -> None:
        with self.lock:
            now = time.monotonic()
            elapsed = now - self.last_time
            self.tokens = min(self.max_burst, self.tokens + elapsed * self.rate)
            self.last_time = now

            if self.tokens < 1.0:
                wait = (1.0 - self.tokens) / self.rate
                time.sleep(wait)
                self.tokens = 0.0
                self.last_time = time.monotonic()
            else:
                self.tokens -= 1.0

    def __call__(self, func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            self.acquire()
            return func(*args, **kwargs)
        return wrapper

