import pytest

def test_rate_limiting_applied():
    limiter = RateLimiter(calls_per_second=4.0, max_burst=1)

    @limiter
    def fast_fn():
        return True

    start = time.monotonic()
    for _ in range(4):
        fast_fn()
    elapsed = time.monotonic() - start
    assert elapsed >= 0.7, f'Expected >= 0.7s, got {elapsed:.2f}s'
